    @Test fun loadChangesMatchWeb() {
        val w = FakeWorld(webPlan())
        val c = PhaseController(w)
        assertTrue(c.loadPlanIntoControls())
        assertTrue(c.phase == Phase.READY)
        assertEquals("battery", true, w.sim["battery"])
        assertEquals("psFlightAltFt", 75.0, (w.sim["psFlightAltFt"] as Number).toDouble(), 1e-9)
        assertEquals("psFlightTargetAltFt", 75.0, (w.sim["psFlightTargetAltFt"] as Number).toDouble(), 1e-9)
        assertEquals("hydAPress", 3000.0, (w.sim["hydAPress"] as Number).toDouble(), 1e-9)
        assertEquals("hydBPress", 3000.0, (w.sim["hydBPress"] as Number).toDouble(), 1e-9)
        assertEquals("parkingBrake", false, w.sim["parkingBrake"])
        assertEquals("autobrake", 4.0, (w.sim["autobrake"] as Number).toDouble(), 1e-9)
        assertEquals("flaps", 5.0, (w.sim["flaps"] as Number).toDouble(), 1e-9)
        assertEquals("fdMode", 2.0, (w.mip["fdMode"] as Number).toDouble(), 1e-9)
        assertEquals("selCrs", 63.0, (w.mip["selCrs"] as Number).toDouble(), 1e-9)
        assertEquals("selHdg", 63.0, (w.mip["selHdg"] as Number).toDouble(), 1e-9)
        assertEquals("apHdgSw", 0.0, (w.mip["apHdgSw"] as Number).toDouble(), 1e-9)
        assertEquals("navResetN", 1.0, (w.mip["navResetN"] as Number).toDouble(), 1e-9)
        assertEquals("planNav", true, w.mip["planNav"])
        assertEquals("planNavStatus", "ARMED - WAITING FOR TAKEOFF", w.mip["planNavStatus"])
        assertEquals("xpdrMode", 2.0, (w.mip["xpdrMode"] as Number).toDouble(), 1e-9)
