    @Test fun startGatesAfterLoadMatchWeb() {
        val w = FakeWorld(webPlan())
        val c = PhaseController(w)
        c.loadPlanIntoControls()
        run { val g = c.canStart(Phase.TAKEOFF); assertTrue(g.ok == true); assertTrue(g.reason == "") }
        run { val g = c.canStart(Phase.CLIMB); assertTrue(g.ok == false); assertTrue(g.reason == "Start with TAKEOFF") }
        run { val g = c.canStart(Phase.CRUISE); assertTrue(g.ok == false); assertTrue(g.reason == "Start with TAKEOFF") }
        run { val g = c.canStart(Phase.DESCENT); assertTrue(g.ok == false); assertTrue(g.reason == "Start with TAKEOFF") }
        run { val g = c.canStart(Phase.APPROACH); assertTrue(g.ok == false); assertTrue(g.reason == "Start with TAKEOFF") }
        run { val g = c.canStart(Phase.LAND); assertTrue(g.ok == false); assertTrue(g.reason == "Start with TAKEOFF") }
